package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;
import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
import java.time.*;import java.util.*;import tools.jackson.databind.json.JsonMapper;

/** Pertenencia limitada al Caso: no otorga roles, ámbito territorial ni reserva. */
public final class EquipoCaso {
 public record Incorporar(long revision,String persona,String fundamento){@Override public String toString(){return "Incorporar[protegido]";}}
 public record Retirar(long revision,String persona,String reasignarPendientesA,String fundamento){@Override public String toString(){return "Retirar[protegido]";}}
 public record Espera(long revision,String faltante,String solicitadoA,Instant solicitadoEn){@Override public String toString(){return "Espera[protegido]";}}
 public record ResolverEspera(long revision,long revisionCaso,String decision,String fundamento){@Override public String toString(){return "ResolverEspera[protegido]";}}
 private final BaseJdbc db;private final NucleoInstitucional core;private final CatalogoLaboratorio cat;private final Clock clock;private final PoliticaAreas areas;
 EquipoCaso(BaseJdbc db,NucleoInstitucional core,CatalogoLaboratorio cat,Clock clock,JsonMapper json){this.db=db;this.core=core;this.cat=cat;this.clock=clock;areas=new PoliticaAreas(db,clock);}
 private static String id(UUID x){if(x==null)throw new FalloTecnico(400);return x.toString();}
 private static UUID uuid(Object x){return UUID.fromString(x.toString());}
 private static long rev(Map<String,Object> r){return ((Number)r.get("revision")).longValue();}
 private static void version(Map<String,Object> r,long v){if(v<0||v!=rev(r))throw new FalloTecnico(409,"VERSION_OBSOLETA");}
 private static void texto(String x){try{cl.nexbyte.siger.contrato.DeclaracionNna.texto(x==null?null:x.replace('\n',' ').replace('\r',' '),2000,true);}catch(IllegalArgumentException e){throw new FalloTecnico(400);}}
 private List<Map<String,Object>> rows(String sql,Object...args){return db.sql.queryForList(sql,args).stream().map(r->{Map<String,Object> m=new LinkedHashMap<>();r.forEach((k,v)->m.put(k.toLowerCase(Locale.ROOT),v));return m;}).toList();}
 boolean colabora(Operador a,Map<String,Object> c){return (areas.profesional(a,c)||areas.jefe(a,c))&&db.sql.queryForObject("SELECT COUNT(*) FROM case_team_access WHERE case_id=? AND actor_id=?",Long.class,c.get("id"),a.id())==1;}
 public boolean participa(Operador a,UUID c){var row=core.caseRow(c);return (a.id().equals(row.get("responsible_id"))&&(areas.profesional(a,row)||areas.jefe(a,row)))||colabora(a,row);}
 public boolean miembro(Operador a,UUID c){core.autorizarCaso(a,c);return participa(a,c);}
 public void autorizarEjecutor(UUID caso,String actor){Operador a;try{a=cat.operador(actor);}catch(FalloTecnico e){throw new FalloTecnico(400,"EJECUTOR_NO_HABILITADO");}if(!participa(a,caso))throw new FalloTecnico(400,"EJECUTOR_FUERA_EQUIPO");}
 private void administra(Operador a,Map<String,Object> c){core.autorizarCaso(a,uuid(c.get("id")));if(!a.id().equals(c.get("responsible_id")))core.head(a,c);}
 public Map<String,Object> bloquear(Operador a,UUID caso){core.bloquearAcceso(a);var c=core.caseRow(caso);core.lock(uuid(c.get("communication_id")));core.autorizarCaso(a,caso);return core.caseRow(caso);}
 private void abierto(Map<String,Object> c){if("CERRADO".equals(c.get("state")))throw new FalloTecnico(409,"CASO_CERRADO");}
 void cambio(UUID caso,Operador a,String code,String reason,Object snapshot){var c=core.caseRow(caso);db.sql.update("UPDATE core_case SET revision=revision+1 WHERE id=?",id(caso));if("REVISION_TERMINO".equals(c.get("state")))db.sql.update("INSERT INTO institution_case_closure_request(case_id,case_revision,mode_code) SELECT case_id,?,mode_code FROM institution_case_closure_request WHERE case_id=? AND case_revision=?",rev(c)+1,id(caso),rev(c));core.u2().historia(uuid(c.get("communication_id")),caso,"CASO",rev(c)+1,a,code,reason,snapshot);core.u2().bumpCom(uuid(c.get("communication_id")));}
 public void tareaCambiada(Operador a,UUID caso,String code){cambio(caso,a,code,"Cambio en agenda del Caso",Map.of());}
 public boolean obligatorias(UUID caso){return db.sql.queryForObject("SELECT COUNT(*) FROM institution_task WHERE resource_type='CASO' AND resource_id=? AND mandatory=TRUE AND state NOT IN ('COMPLETADA','CANCELADA')",Long.class,id(caso))>0;}
 public boolean esperaPendiente(UUID caso){return db.sql.queryForObject("SELECT COUNT(*) FROM case_wait_request WHERE case_id=? AND state IN ('SOLICITADA','CONFIRMADA')",Long.class,id(caso))>0;}
 public boolean enEspera(UUID caso){return db.sql.queryForObject("SELECT COUNT(*) FROM case_wait_request WHERE case_id=? AND state='CONFIRMADA'",Long.class,id(caso))>0;}
 void asumirPrincipal(Operador a,UUID caso,String persona){var rows=db.sql.queryForList("SELECT membership_id FROM case_team_access WHERE case_id=? AND actor_id=?",id(caso),persona);if(rows.isEmpty())return;db.sql.update("DELETE FROM case_team_access WHERE case_id=? AND actor_id=?",id(caso),persona);db.sql.update("UPDATE case_team_member SET state=\'RETIRADO\',revision=revision+1,removed_by=?,removed_ms=?,removal_reason=? WHERE id=?",a.id(),clock.millis(),"Asume responsabilidad principal por reasignación",rows.getFirst().get("membership_id"));var c=core.caseRow(caso);core.event(uuid(c.get("communication_id")),"CASO",caso,a,"COLABORADOR_ASUME_RESPONSABILIDAD");}
 void validarCambioArea(Map<String,Object> c,String nueva){for(var r:db.sql.queryForList("SELECT actor_id FROM case_team_access WHERE case_id=?",c.get("id"))){var a=cat.operador(r.get("actor_id").toString());if(!a.profesionalEn(c.get("unit_code").toString(),c.get("site_id").toString(),nueva)&&!a.jefeEn(c.get("unit_code").toString(),c.get("site_id").toString(),nueva))throw new FalloTecnico(409,"EQUIPO_REQUIERE_CONCILIAR_AREA");}}
 public Resultado incorporar(Operador a,UUID key,UUID caso,Incorporar r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"EQUIPO_INCORPORAR",List.of(caso,r),()->{var c=bloquear(a,caso);administra(a,c);version(c,r.revision());abierto(c);texto(r.fundamento());var member=cat.operador(r.persona());if(!(areas.profesional(member,c)||areas.jefe(member,c)))throw new FalloTecnico(400,"MIEMBRO_FUERA_AMBITO");if(r.persona().equals(c.get("responsible_id"))||db.sql.queryForObject("SELECT COUNT(*) FROM case_team_access WHERE case_id=? AND actor_id=?",Long.class,id(caso),r.persona())>0)throw new FalloTecnico(409,"MIEMBRO_YA_PRESENTE");UUID membership=UUID.randomUUID();db.sql.update("INSERT INTO case_team_member(id,case_id,actor_id,state,revision,joined_by,joined_ms,reason_text) VALUES(?,?,?,'ACTIVO',0,?,?,?)",id(membership),id(caso),r.persona(),a.id(),clock.millis(),r.fundamento());db.sql.update("INSERT INTO case_team_access VALUES(?,?,?)",id(caso),r.persona(),id(membership));cambio(caso,a,"EQUIPO_INTEGRANTE_INCORPORADO",r.fundamento(),Map.of("persona",r.persona(),"incorporacion",id(membership)));core.event(uuid(c.get("communication_id")),"EQUIPO",membership,a,"EQUIPO_PARTICIPACION_ACTUALIZADA");return new Resultado(membership,rev(c)+1);});}
 public Resultado retirar(Operador a,UUID key,UUID caso,Retirar r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"EQUIPO_RETIRAR",List.of(caso,r),()->{var c=bloquear(a,caso);administra(a,c);version(c,r.revision());texto(r.fundamento());var links=db.sql.queryForList("SELECT membership_id FROM case_team_access WHERE case_id=? AND actor_id=?",id(caso),r.persona());if(links.size()!=1)throw new FalloTecnico(404);long pending=db.sql.queryForObject("SELECT COUNT(*) FROM institution_task WHERE resource_type='CASO' AND resource_id=? AND responsible_id=? AND state NOT IN ('COMPLETADA','CANCELADA')",Long.class,id(caso),r.persona());if(pending>0){if(r.reasignarPendientesA()==null||r.persona().equals(r.reasignarPendientesA()))throw new FalloTecnico(409,"RETIRO_REQUIERE_RESOLVER_TAREAS");autorizarEjecutor(caso,r.reasignarPendientesA());core.tareas().transferir(a,caso,r.reasignarPendientesA(),r.persona(),"TAREA_RETIRO_EQUIPO");}db.sql.update("DELETE FROM case_team_access WHERE case_id=? AND actor_id=?",id(caso),r.persona());db.sql.update("UPDATE case_team_member SET state='RETIRADO',revision=revision+1,removed_by=?,removed_ms=?,removal_reason=? WHERE id=?",a.id(),clock.millis(),r.fundamento(),links.getFirst().get("membership_id"));cambio(caso,a,"EQUIPO_INTEGRANTE_RETIRADO",r.fundamento(),Map.of("persona",r.persona(),"tareasTratadas",pending));core.event(uuid(c.get("communication_id")),"EQUIPO",uuid(links.getFirst().get("membership_id")),a,"EQUIPO_PARTICIPACION_ACTUALIZADA");return new Resultado(caso,rev(c)+1);});}
 public void autorizarAviso(Operador a,UUID membership){core.bloquearAcceso(a);var list=db.sql.queryForList("SELECT actor_id,case_id FROM case_team_member WHERE id=?",id(membership));if(list.size()!=1)throw new FalloTecnico(404);var m=list.getFirst();if(a.id().equals(m.get("actor_id")))return;var c=core.caseRow(uuid(m.get("case_id")));administra(a,c);}
 public Map<String,Object> ver(Operador a,UUID caso){return db.transaction(()->{core.bloquearAcceso(a);var c=core.caseRow(caso);core.autorizarCaso(a,caso);var out=new LinkedHashMap<String,Object>();out.put("revision",rev(c));out.put("responsable",c.get("responsible_id"));out.put("administra",a.id().equals(c.get("responsible_id"))||areas.jefe(a,c));out.put("miembros",rows("SELECT * FROM case_team_member WHERE case_id=? ORDER BY joined_ms,id",id(caso)));out.put("esperas",rows("SELECT * FROM case_wait_request WHERE case_id=? ORDER BY requested_ms,id",id(caso)));out.put("enEspera",enEspera(caso));out.put("tareasObligatoriasPendientes",obligatorias(caso));out.put("tareasOrdinariasPendientes",db.sql.queryForObject("SELECT COUNT(*) FROM institution_task WHERE resource_type='CASO' AND resource_id=? AND mandatory=FALSE AND state NOT IN ('COMPLETADA','CANCELADA')",Long.class,id(caso)));out.put("elegibles",cat.operadores().stream().filter(x->areas.profesional(x,c)||areas.jefe(x,c)).map(Operador::id).toList());return out;});}
 public Resultado solicitarEspera(Operador a,UUID key,UUID caso,Espera r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"CASO_SOLICITAR_ESPERA",List.of(caso,r),()->{var c=bloquear(a,caso);version(c,r.revision());if(!"EN_GESTION".equals(c.get("state"))||esperaPendiente(caso))throw new FalloTecnico(409);texto(r.faltante());texto(r.solicitadoA());if(r.solicitadoEn()==null||r.solicitadoEn().isAfter(clock.instant()))throw new FalloTecnico(400);UUID p=UUID.randomUUID();db.sql.update("INSERT INTO case_wait_request(id,case_id,case_revision,requested_by,requested_ms,missing_text,requested_from,requested_at,state,revision) VALUES(?,?,?,?,?,?,?,?,'SOLICITADA',0)",id(p),id(caso),rev(c)+1,a.id(),clock.millis(),r.faltante(),r.solicitadoA(),r.solicitadoEn().toEpochMilli());cambio(caso,a,"ESPERA_ANTECEDENTES_SOLICITADA",r.faltante(),Map.of("solicitud",id(p)));return new Resultado(p,0);});}
 public Resultado resolverEspera(Operador a,UUID key,UUID caso,UUID request,ResolverEspera r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"CASO_DECIDIR_ESPERA",List.of(caso,request,r),()->{var c=bloquear(a,caso);version(c,r.revisionCaso());abierto(c);var found=db.sql.queryForList("SELECT * FROM case_wait_request WHERE id=? AND case_id=?",id(request),id(caso));if(found.size()!=1)throw new FalloTecnico(404);var p=found.getFirst();version(p,r.revision());texto(r.fundamento());String next=r.decision();if(Set.of("CONFIRMADA","RECHAZADA").contains(next)){core.head(a,c);if(!"SOLICITADA".equals(p.get("state")))throw new FalloTecnico(409);}else if("FINALIZADA".equals(next)){if(!Set.of("SOLICITADA","CONFIRMADA").contains(p.get("state")))throw new FalloTecnico(409);}else throw new FalloTecnico(400);db.sql.update("UPDATE case_wait_request SET state=?,revision=revision+1,decided_by=?,decided_ms=?,decision_text=? WHERE id=?",next,a.id(),clock.millis(),r.fundamento(),id(request));cambio(caso,a,"ESPERA_"+next,r.fundamento(),Map.of("solicitud",id(request)));return new Resultado(request,r.revision()+1);});}
}
